//! Compiler builtin API, extracted from `roc docs --builtins`.
//!
//! The database is generated by `tools/extract_builtins.py` and embedded in the
//! binary.  Keeping it as generated data means hover, completion, and signature
//! help for builtins work without a compiler subprocess and without network
//! access.

use std::collections::HashMap;

use serde::{Deserialize, Serialize};

use crate::analysis::DefinitionKey;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum BuiltinKind {
    Type,
    Value,
    Tag,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct BuiltinItem {
    /// Fully qualified name, e.g. `Str.concat` or `List`.
    pub name: String,
    /// Containing module, e.g. `Str`.
    pub module: String,
    /// Last path segment, e.g. `concat`.
    pub short_name: String,
    pub kind: BuiltinKind,
    #[serde(default)]
    pub signature: Option<String>,
    #[serde(default)]
    pub doc: Option<String>,
    /// The raw `:= ...` definition for type entries.
    #[serde(default)]
    pub type_def: Option<String>,
}

impl BuiltinItem {
    pub fn key(&self) -> DefinitionKey {
        DefinitionKey::Builtin {
            full_name: self.name.clone(),
        }
    }

    pub fn kind_string(&self) -> &'static str {
        match self.kind {
            BuiltinKind::Type => "type",
            BuiltinKind::Value => "function",
            BuiltinKind::Tag => "tag",
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct BuiltinModule {
    pub name: String,
    #[serde(default)]
    pub doc: Option<String>,
    pub items: Vec<BuiltinItem>,
}

#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct BuiltinDatabase {
    #[serde(default)]
    pub version: String,
    #[serde(default)]
    pub modules: Vec<BuiltinModule>,
}

/// Fast lookup wrapper around the generated database.
#[derive(Debug, Clone, Default)]
pub struct BuiltinIndex {
    database: BuiltinDatabase,
    by_name: HashMap<String, BuiltinItem>,
    by_module: HashMap<String, usize>,
}

impl BuiltinIndex {
    pub fn empty() -> Self {
        Self::default()
    }

    pub fn from_database(mut database: BuiltinDatabase) -> Self {
        // Type entries carry their tag union in `type_def`; materialize each
        // tag as an item so hover, completion, navigation, and rename treat
        // `Bool.True`, `Try.Ok`, and `Num.RawOrder.After` like any other
        // builtin.
        let mut tags = Vec::new();
        for module in &database.modules {
            for item in &module.items {
                if item.kind != BuiltinKind::Type {
                    continue;
                }
                let Some(type_def) = item.type_def.as_deref() else {
                    continue;
                };
                for tag in tag_names(type_def) {
                    tags.push(BuiltinItem {
                        name: format!("{}.{}", item.name, tag),
                        module: item.module.clone(),
                        short_name: tag,
                        kind: BuiltinKind::Tag,
                        signature: None,
                        doc: None,
                        type_def: None,
                    });
                }
            }
        }
        for tag in tags {
            if database
                .modules
                .iter()
                .flat_map(|module| module.items.iter())
                .any(|item| item.name == tag.name)
            {
                continue;
            }
            if let Some(index) = database
                .modules
                .iter()
                .position(|module| module.name == tag.module)
            {
                database.modules[index].items.push(tag);
            }
        }
        let mut by_name = HashMap::new();
        let mut by_module = HashMap::new();
        for (index, module) in database.modules.iter().enumerate() {
            by_module.insert(module.name.clone(), index);
            for item in &module.items {
                by_name.insert(item.name.clone(), item.clone());
            }
        }
        Self {
            database,
            by_name,
            by_module,
        }
    }

    pub fn load_embedded() -> Self {
        const EMBEDDED: &str = include_str!("../../data/builtins.json");
        match serde_json::from_str::<BuiltinDatabase>(EMBEDDED) {
            Ok(database) => Self::from_database(database),
            Err(error) => {
                eprintln!("hardroc: failed to parse embedded builtin database: {error}");
                Self::empty()
            }
        }
    }

    pub fn version(&self) -> &str {
        &self.database.version
    }

    pub fn modules(&self) -> &[BuiltinModule] {
        &self.database.modules
    }

    pub fn module(&self, name: &str) -> Option<&BuiltinModule> {
        self.by_module
            .get(name)
            .and_then(|index| self.database.modules.get(*index))
    }

    pub fn lookup(&self, full_name: &str) -> Option<&BuiltinItem> {
        if let Some(item) = self.by_name.get(full_name) {
            return Some(item);
        }
        // Accept an unqualified builtin item name when it is unambiguous.
        let mut matches = self
            .database
            .modules
            .iter()
            .flat_map(|module| module.items.iter())
            .filter(|item| item.short_name == full_name);
        let first = matches.next()?;
        if matches.next().is_none() {
            Some(first)
        } else {
            None
        }
    }

    pub fn items_in_module(&self, module: &str) -> impl Iterator<Item = &BuiltinItem> {
        self.module(module)
            .into_iter()
            .flat_map(|module| module.items.iter())
    }

    pub fn types(&self) -> impl Iterator<Item = &BuiltinItem> {
        self.database
            .modules
            .iter()
            .flat_map(|module| module.items.iter())
            .filter(|item| item.kind == BuiltinKind::Type)
    }

    pub fn values(&self) -> impl Iterator<Item = &BuiltinItem> {
        self.database
            .modules
            .iter()
            .flat_map(|module| module.items.iter())
            .filter(|item| item.kind == BuiltinKind::Value)
    }

    /// Builtin tags/constructors that are available unqualified.
    pub fn unqualified_tags(&self) -> impl Iterator<Item = &BuiltinItem> {
        self.database
            .modules
            .iter()
            .flat_map(|module| module.items.iter())
            .filter(|item| item.kind == BuiltinKind::Tag)
    }
}

/// Extract the tag names from a `:= [Red, Green({ .. }), Blue]` definition.
fn tag_names(type_def: &str) -> Vec<String> {
    let Some(start) = type_def.find('[') else {
        return Vec::new();
    };
    let mut depth = 0usize;
    let mut tags = Vec::new();
    let mut current = String::new();
    let mut in_string = false;
    let mut escaped = false;
    for ch in type_def[start..].chars() {
        if in_string {
            if escaped {
                escaped = false;
            } else if ch == '\\' {
                escaped = true;
            } else if ch == '"' {
                in_string = false;
            }
            continue;
        }
        match ch {
            '"' => in_string = true,
            '[' | '(' | '{' => {
                depth += 1;
                if depth == 1 {
                    current.clear();
                }
            }
            ']' | ')' | '}' => {
                if depth == 1 {
                    let trimmed = current.trim();
                    if is_tag_name(trimmed) {
                        tags.push(trimmed.to_string());
                    }
                    current.clear();
                }
                depth = depth.saturating_sub(1);
            }
            ',' if depth == 1 => {
                let trimmed = current.trim();
                if is_tag_name(trimmed) {
                    tags.push(trimmed.to_string());
                }
                current.clear();
            }
            _ if depth == 1 => current.push(ch),
            _ => {}
        }
    }
    tags
}

fn is_tag_name(name: &str) -> bool {
    let mut chars = name.chars();
    matches!(chars.next(), Some(ch) if ch.is_ascii_uppercase())
        && chars.all(|ch| ch.is_ascii_alphanumeric() || ch == '_')
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn embedded_database_loads() {
        let index = BuiltinIndex::load_embedded();
        assert!(!index.modules().is_empty(), "embedded builtins are empty");
        assert!(index.module("Str").is_some());
        assert!(index.lookup("Str.concat").is_some());
        let boolean = index.lookup("Bool.True").expect("Bool.True");
        assert_eq!(boolean.kind, BuiltinKind::Tag);
        let result = index.lookup("Try.Ok").expect("Try.Ok");
        assert_eq!(result.kind, BuiltinKind::Tag);
        let order = index.lookup("Num.RawOrder.After").expect("raw order tag");
        assert_eq!(order.kind, BuiltinKind::Tag);
    }
}
